changeSet.sql:
DO $$
DECLARE
    missing_sentences int;
    missing_pads int;
BEGIN
    SELECT count(*) INTO missing_sentences FROM note n
    WHERE n.sentence_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM note_sentence ns WHERE ns.note_id = n.note_id AND ns.sentence_id = n.sentence_id);
    SELECT count(*) INTO missing_pads FROM note n
    WHERE n.scratchpad_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM note_scratchpad p WHERE p.note_id = n.note_id AND p.scratchpad_id = n.scratchpad_id);
    IF missing_sentences > 0 OR missing_pads > 0 THEN
        RAISE EXCEPTION 'note placements: % sentence home(s) and % pad home(s) have no placement row — refusing to drop the legacy columns',
            missing_sentences, missing_pads;
    END IF;
END
$$;

DROP TRIGGER IF EXISTS trg_note_legacy_home_mirror ON note;
DROP FUNCTION IF EXISTS note_legacy_home_mirror();

ALTER TABLE note DROP COLUMN sentence_id;
ALTER TABLE note DROP COLUMN scratchpad_id;
ALTER TABLE note DROP COLUMN position;
